'use strict';
// Earned story access is separate from whether an edited answer is currently checked.
const pageOrder=['case2','mission1','trail','mission2','after2','mission3','after3','mission4','after4','mission5','after5','reflection'];
more.solvedThrough=Number.isInteger(more.solvedThrough)?Math.max(0,Math.min(5,more.solvedThrough)):0;
for(let n=1;n<=5;n++){const a=n===1?s:more[n];if(n===more.solvedThrough+1&&a.verified&&(n===1?evaluateAnswer(a):evaluateMore(n,a)).kind==='success')more.solvedThrough=n;}
function missionSolved(n){return more.solvedThrough>=n;}
function lastUnlockedRoute(){return more.solvedThrough>=5?'reflection':`mission${more.solvedThrough+1}`;}
function routeAllowed(route){const i=pageOrder.indexOf(route);return i<0||i<=pageOrder.indexOf(lastUnlockedRoute());}
function awardMission(n){if(n===more.solvedThrough+1){more.solvedThrough=n;saveMore();}mountNavigation();}
function mountNavigation(){if(!app.insertAdjacentHTML)return;const old=document.getElementById('page-navigation');if(old)old.remove();const route=location.hash.slice(1),i=pageOrder.indexOf(route);if(i<0)return;const next=pageOrder[i+1],allowed=next&&routeAllowed(next);app.insertAdjacentHTML('afterbegin',`<nav id="page-navigation" class="page-navigation" aria-label="Story pages"><a class="button secondary" href="#${i? pageOrder[i-1]:'library'}">← ${i?'Previous Page':'Case library'}</a>${next?allowed?`<a class="button secondary" href="#${next}">Next Page →</a>`:'<button class="secondary" disabled>Next Page →</button>':''}${next&&!allowed?'<p class="status">Solve this mission to unlock the next story page.</p>':''}</nav>`);}
let selectedTag=null;
function routeBuilder(a){return `<div class="check"><strong>Original plan</strong><p>Blue Arch → Striped Skybridge → Control Booth → recall DASH-3</p></div><h2>Your route map</h2><div class="map-scroll" tabindex="0" role="region" aria-label="Route map; scroll sideways on small screens"><img class="route-map" src="assets/case2-map.png" alt="Prototype Plaza connects to Blue Arch. Blue Arch branches to the closed Striped Skybridge above and Workshop Hall below. Both paths lead toward Control Booth; the lower path goes through Ground Passage."></div><details><summary>Read the map connections</summary><ul>${edges.map(([x,y])=>`<li>${x} ↔ ${y}${[x,y].includes('Striped Skybridge')?' — CLOSED':''}</li>`).join('')}</ul></details><h2>Your route</h2><p>The team is at Blue Arch. Drag location tags into the steps to plan an open route to Control Booth. You can also select a tag, then select a step.</p><div class="tag-bank" aria-label="Location tags">${[...new Set(edges.flat())].map(p=>`<button class="location-tag secondary" data-tag="${p}" aria-pressed="${selectedTag?.place===p&&selectedTag.from===null}">${p}</button>`).join('')}</div><p id="route-notice" role="status">${selectedTag?'Selected '+esc(selectedTag.place)+'. Choose a step.':'Choose a location tag to begin.'}</p><ol class="route-slots">${a.route.map((p,i)=>`<li class="route-slot" data-drop="${i}"><strong>Step ${i+1}${i===0?' · Start here':''}</strong><button class="location-tag secondary" ${i===0?'disabled':`data-tag="${p}" data-from="${i}"`} >${p}</button>${i?`<button class="secondary" data-place="${i}" aria-label="Place selected tag at step ${i+1}">Place selected tag</button><button class="secondary" data-remove="${i}" aria-label="Remove step ${i+1}">Remove</button>`:''}</li>`).join('')}<li class="route-slot empty" data-drop="${a.route.length}"><strong>Step ${a.route.length+1}</strong><button class="secondary" data-place="${a.route.length}">Place selected tag here</button></li></ol>`;}
function placeRouteTag(route,tag,index){if(!tag||!edges.flat().includes(tag.place)||index<1||index>route.length)return false;if(tag.from!==null){if(tag.from<1||tag.from>=route.length)return false;const [p]=route.splice(tag.from,1);route.splice(Math.min(index,route.length),0,p);}else if(index===route.length)route.push(tag.place);else route[index]=tag.place;return true;}
function bindRouteBuilder(changed,redraw){
const apply=index=>{if(!placeRouteTag(more[4].route,selectedTag,index))return;selectedTag=null;changed();redraw();document.getElementById('route-notice').textContent='Route updated. You can keep building or check your answer.';};
app.querySelectorAll('[data-place]').forEach(e=>e.onclick=()=>apply(Number(e.dataset.place)));
app.querySelectorAll('[data-remove]').forEach(e=>e.onclick=()=>{more[4].route.splice(Number(e.dataset.remove),1);selectedTag=null;changed();redraw();});
app.querySelectorAll('[data-tag]').forEach(e=>{const tag=()=>({place:e.dataset.tag,from:e.dataset.from===undefined?null:Number(e.dataset.from)});let start=null,dragging=false,suppressClick=false;
e.onclick=()=>{if(suppressClick){suppressClick=false;return;}selectedTag=tag();app.querySelectorAll('[data-tag]').forEach(b=>b.setAttribute('aria-pressed',b===e?'true':'false'));document.getElementById('route-notice').textContent='Selected '+selectedTag.place+'. Choose a step.';};
e.onpointerdown=event=>{if(event.button!==0)return;start={x:event.clientX,y:event.clientY};dragging=false;e.setPointerCapture(event.pointerId);};
e.onpointermove=event=>{if(!start)return;if(Math.hypot(event.clientX-start.x,event.clientY-start.y)>6){dragging=true;e.classList.add('dragging');app.querySelectorAll('[data-drop]').forEach(slot=>slot.classList.remove('drop-target'));const slot=document.elementFromPoint(event.clientX,event.clientY)?.closest('[data-drop]');if(slot&&Number(slot.dataset.drop)>0)slot.classList.add('drop-target');}};
e.onpointerup=event=>{if(!start)return;start=null;e.classList.remove('dragging');app.querySelectorAll('[data-drop]').forEach(slot=>slot.classList.remove('drop-target'));if(dragging){suppressClick=true;selectedTag=tag();const slot=document.elementFromPoint(event.clientX,event.clientY)?.closest('[data-drop]');if(slot&&Number(slot.dataset.drop)>0)apply(Number(slot.dataset.drop));else document.getElementById('route-notice').textContent='Choose a numbered step for '+selectedTag.place+'.';}};
e.onpointercancel=()=>{start=null;dragging=false;e.classList.remove('dragging');app.querySelectorAll('[data-drop]').forEach(slot=>slot.classList.remove('drop-target'));};});}
